let saved={};try{saved=JSON.parse(localStorage.getItem('a-quarko-preferences'))||{};}catch{}
let language=['en','cs'].includes(saved.language)?saved.language:(navigator.language?.startsWith('cs')?'cs':'en');
let dark=typeof saved.dark==='boolean'?saved.dark:matchMedia('(prefers-color-scheme: dark)').matches;
let themeCallback=()=>{};
const originalText=new WeakMap(),originalAttributes=new WeakMap();
function save(){try{localStorage.setItem('a-quarko-preferences',JSON.stringify({language,dark}));}catch{}}
export function translate(text){
  if(language==='en')return text;
  if(cs[text])return cs[text];
  const lives=text.match(/^(\d+) little lives\. One tiny ecosystem\.$/);
  if(lives){const n=Number(lives[1]);return `${n} ${n===1?'malý život':n>=2&&n<=4?'malé životy':'malých životů'}. Jeden drobný ekosystém.`;}
  if(/^\d+(\.\d+)?x$/.test(text))return text.replace('.',',');
  return text;
}
const observer=new MutationObserver(localize);
function localize(){
  observer.disconnect();
  const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walk.nextNode()){
    const node=walk.currentNode;if(node.parentElement.closest('script,style,option[data-language]'))continue;
    const value=node.nodeValue,previous=originalText.get(node),source=previous&&value===previous.rendered?previous.source:value;
    const trimmed=source.trim(),rendered=source.replace(trimmed,translate(trimmed));
    if(rendered!==value)node.nodeValue=rendered;originalText.set(node,{source,rendered});
  }
  for(const el of document.querySelectorAll('[aria-label],[title]')){
    const attrs=originalAttributes.get(el)||{};
    for(const key of ['aria-label','title'])if(el.hasAttribute(key)){
      const value=el.getAttribute(key),old=attrs[key],source=old&&value===old.rendered?old.source:value,rendered=translate(source);
      if(value!==rendered)el.setAttribute(key,rendered);attrs[key]={source,rendered};
    }
    originalAttributes.set(el,attrs);
  }
  document.documentElement.lang=language;document.title=language==='cs'?'A-quarko — živé akvárium':'A-quarko — a living aquarium';
  observer.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','title']});
}
function applyTheme(){
  document.body.classList.toggle('evening',dark);document.documentElement.dataset.theme=dark?'dark':'light';
  document.documentElement.style.colorScheme=dark?'dark':'light';
  const button=document.querySelector('#light');button.textContent=dark?'☾':'☼';button.setAttribute('aria-label',dark?'Enable light mode':'Enable dark mode');button.title=dark?'Enable light mode':'Enable dark mode';button.setAttribute('aria-pressed',String(dark));themeCallback(dark);localize();
}
export function initPreferences(onThemeChange){
  themeCallback=onThemeChange;
  const controls=document.createElement('div');controls.id='preferences';controls.innerHTML='<label class="sr-only" for="language">Language</label><select id="language" aria-label="Language"><option data-language value="en">English</option><option data-language value="cs">Čeština</option></select>';document.body.append(controls);
  const select=controls.querySelector('select');select.value=language;select.onchange=()=>{language=select.value;save();localize();};
  document.querySelector('#light').onclick=()=>{dark=!dark;save();applyTheme();};applyTheme();
}
